settings.shader:
vec3 palette(float t) {
    return 0.5 + 0.5*cos(6.2831853*(t+vec3(0.0,0.33,0.67)));
}
mat2 turn(float a) {return mat2(cos(a),-sin(a),sin(a),cos(a));}

void mainImage(out vec4 color,in vec2 pixel) {
    vec2 p=(pixel*2.0-iResolution.xy)/iResolution.y;
    p=turn(iTime*rate*0.09)*p/zoom;
    float t=iTime*rate;
    float radius=length(p), angle=atan(p.y,p.x);
    float wave=radius*detail+sin(angle*3.0-t)*0.12-t*0.25;
    float d=abs(fract(wave)-0.5);
    float line=exp(-d*d/(width*width));
    float arc=0.6+0.4*sin(angle*5.0+t+radius*4.0);
    vec3 rgb=palette(hue+radius*0.09-angle*0.035)*line*arc;
    rgb+=palette(hue+0.3)*exp(-d*18.0)*glow*0.3;
    rgb*=exp(-radius*radius*0.12);
    color=vec4(rgb,1.0);
}

vec3 palette(float t) {
    return 0.5 + 0.5*cos(6.2831853*(t+vec3(0.0,0.33,0.67)));
}
mat2 turn(float a) {return mat2(cos(a),-sin(a),sin(a),cos(a));}

float hash2(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise2(vec2 p) {
 vec2 a=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);
 return mix(mix(hash2(a),hash2(a+vec2(1,0)),f.x),mix(hash2(a+vec2(0,1)),hash2(a+vec2(1,1)),f.x),f.y);
}
float fbm(vec2 p) {
 float v=0.0,a=0.5;
 for(int k=0;k<5;k++){v+=a*noise2(p);p=turn(0.6)*p*2.02+vec2(1.7,2.3);a*=0.5;}
 return v;
}
void mainImage(out vec4 color,in vec2 pixel) {
 vec2 p=(pixel*2.0-iResolution.xy)/iResolution.y*scale;
 float t=iTime*rate;
 vec2 q=vec2(fbm(p+vec2(0,t*0.12)),fbm(p+vec2(4.2,-t*0.09)));
 float f=fbm(p+warp*q+vec2(t*0.08,-t*0.06));
 float bands=0.5+0.5*sin(f*detail*6.2831853+t*0.15);
 vec3 dark=vec3(0.005,0.015,0.025);
 vec3 rgb=mix(dark,palette(f*0.7+hue),pow(bands,1.4));
 float edge=pow(1.0-abs(bands*2.0-1.0),10.0);
 color=vec4(rgb+edge*shine*vec3(0.4,0.7,0.8),1.0);
}

vec3 palette(float t) {
    return 0.5 + 0.5*cos(6.2831853*(t+vec3(0.0,0.33,0.67)));
}
mat2 turn(float a) {return mat2(cos(a),-sin(a),sin(a),cos(a));}

void mainImage(out vec4 color,in vec2 pixel) {
 vec2 p=(pixel*2.0-iResolution.xy)/iResolution.y/zoom;
 float t=iTime*rate;
 vec3 rgb=vec3(0.006,0.008,0.025);
 for(int k=0;k<9;k++) {
  float f=float(k);
  float y=sin(p.x*1.7+t*0.6+f*0.35)*0.38+sin(p.x*0.75-t*0.24+f)*0.18+(f-4.0)*spacing;
  float d=abs(p.y-y);
  vec3 ink=palette(hue+f*0.065+p.x*0.05);
  rgb+=ink*(exp(-d*d/(width*width))*0.7+exp(-d*16.0)*glow*0.14);
 }
 color=vec4(rgb,1.0);
}

vec3 palette(float t) {
    return 0.5 + 0.5*cos(6.2831853*(t+vec3(0.0,0.33,0.67)));
}
mat2 turn(float a) {return mat2(cos(a),-sin(a),sin(a),cos(a));}

void mainImage(out vec4 color,in vec2 pixel) {
 vec2 p=(pixel*2.0-iResolution.xy)/iResolution.y;
 p=turn(iTime*rate*0.1)*p;
 float t=iTime*rate;
 float a=atan(p.y,p.x),r=length(p);
 float ring=0.55+sin(a*petals+t)*0.12+sin(a*3.0-t*0.7)*0.08;
 float d=abs(r-ring);
 vec3 rgb=palette(hue+a*0.08)*exp(-d*d/(width*width));
 rgb+=palette(hue+0.2)*exp(-d*12.0)*glow*0.22;
 float spokes=pow(0.5+0.5*cos(a*petals*2.0+t),24.0);
 rgb+=palette(hue+0.4)*spokes*exp(-abs(r-0.85)*18.0)*0.5;
 color=vec4(rgb,1.0);
}
